set res(_res: Response | undefined) {
  if (this.#res && _res) {
    _res = createResponseInstance(_res.body, _res)
    for (const [k, v] of this.#res.headers.entries()) {
      if (k === 'content-type') {
        continue
      }
      if (k === 'set-cookie') {
        const cookies = this.#res.headers.getSetCookie()
        _res.headers.delete('set-cookie')
        for (const cookie of cookies) {
          _res.headers.append('set-cookie', cookie)
        }
      } else {
        _res.headers.set(k, v)
      }
    }
  }
  this.#res = _res
  this.finalized = true
}

input.newString:
set res(_res: Response | undefined) {
  if (this.#res && _res) {
    const contextCookies = this.#res.headers.getSetCookie()
    _res = createResponseInstance(_res.body, _res)
    for (const [k, v] of this.#res.headers.entries()) {
      if (k === 'content-type' || k === 'set-cookie') {
        continue
      }
      _res.headers.set(k, v)
    }
    if (contextCookies.length) {
      // Keep cookies from both responses. A Response created from `c.res`
      // (e.g. by `c.text()`) already contains the context's cookies, so
      // deduplicate them instead of appending the same cookie twice.
      const responseCookies = _res.headers.getSetCookie()
      _res.headers.delete('set-cookie')
      for (const cookie of new Set([...contextCookies, ...responseCookies])) {
        _res.headers.append('set-cookie', cookie)
      }
    }
  }
  this.#res = _res
  this.finalized = true
}

